import time

def get_best_schedule(workload, num_seqs):
    """
    Conflict-window-block-packing with ruin-and-recreate polish.

    Approach: (1) build a conflict graph from shared data-item keys via
    workload.get_txn_ops; (2) partition transactions into connected
    components with union-find; (3) order each cluster: exhaustive optimum
    for clusters of <=7 txns (brute force over permutations with memoized
    true simulator cost), greedy best-insertion for larger ones; (4) merge
    cluster orderings by repeatedly appending the cluster head whose full
    prefix has minimal true cost; (5) polish with ruin-and-recreate
    (random window or conflict-linked block removal + true-best reinsertion),
    accepting strict improvements only. Identity fallback and hard 100s
    per-workload deadline guarantee validity and fit the 360s budget.
    """
    n = workload.num_txns
    if n == 0:
        return 0, []
    deadline = time.time() + 100.0
    cache = {}

    def cost(seq):
        key = tuple(seq)
        c = cache.get(key)
        if c is None:
            c = workload.get_opt_seq_cost(list(seq))
            cache[key] = c
        return c

    # Fallback: identity permutation (always valid).
    best_seq = list(range(n))
    best_cost = cost(best_seq)

    # --- (1) conflict graph: keys per txn ---
    txn_keys = {}
    try:
        for t in range(n):
            keys = set()
            try:
                ops = workload.get_txn_ops(t)
            except Exception:
                ops = []
            for op in ops:
                try:
                    keys.add(op.key)
                except AttributeError:
                    try:
                        keys.add(op[1])
                    except Exception:
                        pass
            txn_keys[t] = keys
    except Exception:
        txn_keys = {t: set() for t in range(n)}

    # --- (2) union-find on shared keys -> connected components ---
    key_map = {}
    parent = list(range(n))

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    for t in range(n):
        for k in txn_keys.get(t, ()):
            if k in key_map:
                rt, rk = find(t), find(key_map[k])
                if rt != rk:
                    parent[rt] = rk
            else:
                key_map[k] = t

    clusters = {}
    for t in range(n):
        clusters.setdefault(find(t), []).append(t)
    cluster_lists = [sorted(v) for v in clusters.values()]
    cluster_lists.sort(key=len)

    # --- (3) per-cluster ordering ---
    def brute_order(members):
        """Exhaustive best ordering of a small cluster by true cost."""
        best_ord, best_c = None, None
        m = len(members)
        # Heap-based permutation enumeration with early deadline bail.
        def permute(prefix, rest):
            nonlocal best_ord, best_c
            if time.time() > deadline:
                return
            if not rest:
                c = cost(prefix)
                if best_c is None or c < best_c:
                    best_c, best_ord = c, list(prefix)
                return
            for i in range(len(rest)):
                permute(prefix + [rest[i]], rest[:i] + rest[i + 1:])
        permute([], list(members))
        return best_ord if best_ord is not None else list(members)

    def greedy_order(members):
        """Greedy best-insertion ordering of a larger cluster."""
        cur = [members[0]]
        for t in members[1:]:
            if time.time() > deadline:
                cur.append(t)
                continue
            best_pos, best_c = 0, None
            for pos in range(len(cur) + 1):
                cand = cur[:pos] + [t] + cur[pos:]
                c = cost(cand)
                if best_c is None or c < best_c:
                    best_c, best_pos = c, pos
            cur.insert(best_pos, t)
        return cur

    ordered_clusters = []
    for members in cluster_lists:
        if len(members) <= 7:
            ordered_clusters.append(brute_order(members))
        else:
            ordered_clusters.append(greedy_order(members))
        if time.time() > deadline:
            break

    # Remaining unprocessed clusters (deadline hit): identity order.
    done = set(t for oc in ordered_clusters for t in oc)
    if len(done) < n:
        rest = sorted(set(range(n)) - done)
        ordered_clusters.append(rest)

    # --- (4) merge cluster orderings by minimal true prefix cost ---
    merged = []
    while ordered_clusters:
        if time.time() > deadline:
            for oc in ordered_clusters:
                merged.extend(oc)
            break
        best_ci, best_c = 0, None
        for ci in range(len(ordered_clusters)):
            c = cost(merged + ordered_clusters[ci])
            if best_c is None or c < best_c:
                best_c, best_ci = c, ci
        merged.extend(ordered_clusters.pop(best_ci))

    if len(merged) == n:
        c = cost(merged)
        if c < best_cost:
            best_cost, best_seq = c, merged[:]

    # --- (5) ruin-and-recreate polish ---
    def ruin_block(seq):
        """Random window or conflict-linked block to remove."""
        if txn_keys and random.random() < 0.5:
            seed = random.randrange(n)
            block = {seed}
            seed_keys = txn_keys.get(seed, set())
            for t in range(n):
                if t != seed and txn_keys.get(t, set()) & seed_keys:
                    block.add(t)
                    if len(block) >= 25:
                        break
            if len(block) < 3:
                return None
            return [t for t in seq if t in block]
        lo = random.randrange(n)
        hi = min(n, lo + random.randint(10, min(25, n)))
        return seq[lo:hi]

    def recreate(seq, removed):
        """Reinsert removed txns at true-best positions, one at a time."""
        cur = seq[:]
        for t in removed:
            best_pos, best_c = None, None
            for pos in range(len(cur) + 1):
                cand = cur[:pos] + [t] + cur[pos:]
                c = cost(cand)
                if best_c is None or c < best_c:
                    best_c, best_pos = c, pos
                if time.time() > deadline:
                    break
            cur = cur[:best_pos] + [t] + cur[best_pos:]
        return cur

    cur_seq, cur_cost = best_seq[:], best_cost
    while time.time() < deadline:
        removed = ruin_block(cur_seq)
        if not removed:
            continue
        rem_set = set(removed)
        partial = [t for t in cur_seq if t not in rem_set]
        cand = recreate(partial, removed)
        c = cost(cand)
        if c < cur_cost:
            cur_seq, cur_cost = cand, c
            if c < best_cost:
                best_cost, best_seq = c, cand[:]
        elif c == cur_cost and random.random() < 0.3:
            cur_seq, cur_cost = cand, c
        elif random.random() < 0.05:
            cur_seq, cur_cost = best_seq[:], best_cost

    assert len(set(best_seq)) == n
    return best_cost, best_seq

# EVOLVE-BLOCK-END

def get_random_costs():
    workload_size = 100
    workload = Workload(WORKLOAD_1)

    makespan1, schedule1 = get_best_schedule(workload, 10)
    cost1 = workload.get_opt_seq_cost(schedule1)

    workload2 = Workload(WORKLOAD_2)
    makespan2, schedule2 = get_best_schedule(workload2, 10)
    cost2 = workload2.get_opt_seq_cost(schedule2)

    workload3 = Workload(WORKLOAD_3)
    makespan3, schedule3 = get_best_schedule(workload3, 10)
    cost3 = workload3.get_opt_seq_cost(schedule3)
    print(cost1, cost2, cost3)
    return cost1 + cost2 + cost3, [schedule1, schedule2, schedule3]


if __name__ == "__main__":
    makespan, schedule = get_random_costs()
    print(f"Makespan: {makespan}")

